        public static bool Has(int number) => number >= 1 && number <= Rows.GetLength(0) && Rows[number - 1, 0] == number;

        public static LevelDefinition Build(int number)
        {
            int r = number - 1;
            var def = LevelLibrary.Draft(number, Rows[r, 6]);
            def.MaxMoves = Rows[r, 1];
            def.Goals = LevelLibrary.GoalsFor(def, Rows[r, 2], Rows[r, 3]);
            def.TwoStarScore = Rows[r, 4];
            def.ThreeStarScore = Rows[r, 5];
            return def;
        }
